const safe = (name) => {
  try {
    return $(name).all().map((i) => i.json).filter((j) => j && !j.error)
  } catch (e) {
    return []
  }
}

const agenda = safe('Agenda du jour').map((e) => ({
  titre: e.summary ?? '(sans titre)',
  debut: e.start?.dateTime ?? e.start?.date ?? null,
  fin: e.end?.dateTime ?? e.end?.date ?? null,
  invites: Array.isArray(e.attendees) ? e.attendees.length : 0,
}))

const cockpit = safe('État cockpit')

const calls = safe('Calls récents').map((c) => ({
  titre: c.titre,
  date: c.date,
  extrait: String(c.extrait ?? '').slice(0, 2000),
}))

const emails = safe('Emails récents').map((m) => ({
  de: m.from ?? m.From ?? '',
  sujet: m.subject ?? m.Subject ?? '(sans objet)',
  extrait: String(m.snippet ?? '').slice(0, 140),
}))

return [{
  json: {
    date: $now.setLocale('fr').toFormat("cccc d LLLL yyyy"),
    agenda,
    cockpit,
    emails,
    calls,
  },
}]
